stock = {"GS-100": 3, "GS-118": 9}

def scan_below_floor():
    return [s for s, q in stock.items() if q < 5]

def restock_low_items():
    from inventory import reserve_stock
    for sku in scan_below_floor():
        reserve_stock(sku, 1)

